import { create } from "zustand";

export interface User {
  _id: string;
  userName: string;
  email: string;
  userType: string;
  createdAt: string;
  updatedAt: string;
  __v: number;
  coins: number;
}

interface AuthState {
  isAuthenticated: boolean;
  token: string | null;
  user: User | null;
  login: (token: string, user: User) => void;
  logout: () => void;
}

export const useAuthStore = create<AuthState>((set) => ({
  isAuthenticated: false,
  token: null,
  user: null,
  login: (token: string, user: User) => {
    set({
      isAuthenticated: true,
      token,
      user,
    });
  },
  logout: () => {
    set({
      isAuthenticated: false,
      token: null,
      user: null,
    });
  },
}));
